    ||(inn.schedule_request&&typeof inn.schedule_request==='object'&&!Array.isArray(inn.schedule_request))
    ||r.task_type==='schedule_build'
    ||String(r.build_mode||inn.build_mode||sr.build_mode||'').trim()
